{"operationName":"cartAddItem","query":"
  mutation cartAddItem($input: AddCartInput) {
    cartAddItem(input: $input) {
      cartCookieValue
      cartId
      currency
      items {
        ...CartItemFragment
      }
      quantity
      isOnlyEGC
      price {
        subtotal
      }
    }
  }

  fragment CartItemFragment on CartItem {
    itemId
    quantity
    size
    index
    color
    colorCode
    shipmentId
    productCode
    product {
      code
      sku
      variant
      skuCode
      description {
        short
      }
      mainImage {
        url
      }
      price {
        list
        final
      }
      itemPromo {
        promoPrice
        promoText
      }
      status {
        code
        details
        backOrdered
        backOrderDate
        finalSale
        lowInStock
        priceChange
        marketPlace
        marketPlaceMessage
        otherVariantsAvailable
        freeGift
        preOrdered
        excludedFromPromo
      }
      personalization {
        personalizeType
        style
        type
        text
        threadColor
        usePromoPrice
        monogramLocation
        monogramPrice {
          displayPrice
          salePrice
          unitPrice
          totalPrice
        }
      }
      giftCard {
        type
        sentDate
      }
    }
  }

","variables":{"input":{"items":[{"skuCode":"99107521299","skuID":"NaN","quantity":1,"shipmentId":"HOME"}]}}}

